"""Functional requirements and executable-review acceptance scenarios."""


def req(number, title, br, basis, description, *criteria, priority="MUST"):
    return {
        "id": f"FR-{number:03d}", "title": title, "br": br.split(),
        "basis": basis, "description": description,
        "criteria": list(criteria), "priority": priority,
    }


